using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF Core 9 breaking change: Migrate() now manages its own transactions.
    // Wrapping it in a user transaction throws:
    //   "A transaction was started before applying migrations."
    // Fix: call Migrate() directly without an external transaction.
    void ApplyMigrations(AppDbContext db)
    {
        db.Database.Migrate();
    }
}

