using Microsoft.EntityFrameworkCore;

// Demonstrates EF Core 9 Cosmos DB breaking changes and their fixes.
// Apply these patterns to your separate Cosmos DB project.

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type".
        // Existing documents use the old name, so explicitly configure it.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: id property no longer contains the discriminator.
        // EF8 stored ids as "Session|abc123"; EF9 stores just "abc123".
        // Preserve old format so existing documents remain accessible.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

// Breaking change 3: Sync I/O is no longer supported on the Cosmos provider.
// Synchronous methods (ToList(), SaveChanges(), First(), etc.) now throw.
// Fix: convert all Cosmos queries/operations to async equivalents.
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (throws in EF Core 9):
    //   var sessions = _db.Sessions.Where(s => s.Name == name).ToList();
    //   _db.SaveChanges();

    // AFTER (use async):
    public async Task<List<Session>> GetSessionsAsync(string name)
    {
        return await _db.Sessions.Where(s => s.Name == name).ToListAsync();
    }

    public async Task SaveAsync()
    {
        await _db.SaveChangesAsync();
    }
}

